insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('aaaa0006-0000-4000-8000-000000000004', 'en', null, 'German — Seminar & Exam Mastery', 'An advanced CEFR C1 seminar that sharpens academic and professional German for exam success: master Nominalstil and cohesive discourse, structure a formal Erörterung, summarize and paraphrase dense sources, and defend a position under Goethe- and TestDaF-style pressure. Aligned to CEFR C1; structure adapted from open advanced German curricula on OER Commons (CC BY 4.0).', 'C1', 'exam', 13, true, 'language', '{aaaa0006-0000-4000-8000-000000000005}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'aaaa0006-0000-4000-8000-000000000004', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Wissenschaftssprache und idiomatische Präzision', 'vocab', '{"items":[{"term":"darlegen","translation":"to set out, to expound (formally)","ipa":"ˈdaːɐ̯ˌleːɡn̩","example":"Die Autorin legt ihre These im ersten Abschnitt schlüssig dar."},{"term":"erörtern","translation":"to discuss, to examine critically","ipa":"ɛɐ̯ˈœʁtɐn","example":"In der Prüfung sollen Sie ein umstrittenes Thema differenziert erörtern."},{"term":"sich beziehen auf","translation":"to refer to / relate to (+ acc.)","ipa":"zɪç bəˈtsiːən aʊf","example":"Der Verfasser bezieht sich auf eine aktuelle Studie zur Mediennutzung."},{"term":"in Anbetracht","translation":"in view of, considering (+ gen.)","ipa":"ɪn ˈanbəˌtʁaxt","example":"In Anbetracht der Datenlage erscheint diese Forderung überzogen."},{"term":"einen Zusammenhang herstellen","translation":"to establish a connection","ipa":"ˈaɪnən tsuˈzamənˌhaŋ ˈheːɐ̯ˌʃtɛln̩","example":"Es gilt, einen Zusammenhang zwischen Ursache und Wirkung herzustellen."},{"term":"der springende Punkt","translation":"the crux, the key point (idiom.)","ipa":"deːɐ̯ ˈʃpʁɪŋəndə pʊŋkt","example":"Der springende Punkt ist nicht die Kosten, sondern die langfristige Wirkung."},{"term":"etwas ins Verhältnis setzen","translation":"to put something into perspective","ipa":"ˈɛtvas ɪns fɛɐ̯ˈhɛltnɪs ˈzɛtsn̩","example":"Man muss die Zahlen ins Verhältnis zur Bevölkerungsgröße setzen."}]}'::jsonb, 'At C1 the register shift matters as much as the word: verbs like darlegen and erörtern replace the neutral sagen and besprechen. Many of these items govern a fixed preposition and case (sich beziehen auf + accusative, hinweisen auf + accusative) — learn the whole frame, not just the headword.', 12),
  (2, 'Nominalstil und komplexe Satzgefüge', 'grammar', '{"sections":[{"heading":"Was Nominalstil leistet","text":"Academic German compresses verbs into nouns to sound objective and dense. A verbal clause like ''weil die Preise steigen'' becomes the nominal phrase ''wegen des Steigens der Preise'' or, more idiomatically, ''aufgrund steigender Preise''. The action is now carried by a noun (das Steigen, der Anstieg), and the agent recedes. This nominal register dominates exam texts, reports and abstracts."},{"heading":"Nominalisierung ↔ Verbalisierung","text":"You must move fluently in both directions. Verbal: ''Nachdem man die Daten ausgewertet hatte, ...'' → Nominal: ''Nach Auswertung der Daten ...''. Verbal: ''Das Projekt scheiterte, weil die Mittel fehlten.'' → Nominal: ''Das Projekt scheiterte aufgrund fehlender Mittel.'' In a summary you nominalize to condense; when explaining, you verbalize to stay clear. Watch the case the new preposition demands: wegen and aufgrund take the genitive (wegen des Regens)."},{"heading":"Funktionsverbgefüge","text":"A hallmark of formal German is the light-verb construction, where a pale verb carries a nominal core: ''eine Entscheidung treffen'' (= entscheiden), ''zur Sprache bringen'' (= ansprechen), ''in Frage stellen'' (= bezweifeln), ''Kritik üben an'' (= kritisieren). They raise the register instantly: ''Der Redner stellte die gängige Annahme in Frage'' reads far more formally than ''Der Redner bezweifelte die Annahme.''"},{"heading":"Erweiterte Attribute und Schachtelsätze","text":"C1 writing packs information into extended participial attributes before the noun: ''die in der Studie erhobenen und sorgfältig ausgewerteten Daten'' (the data collected in the study and carefully analysed). Read such phrases from the article outward to the noun, then back to the participle. Deploy them sparingly in your own writing — one dense attribute per sentence keeps prose readable rather than opaque."}]}'::jsonb, null, 15),
  (3, 'Konnektoren und Textkohäsion im Essay', 'grammar', '{"sections":[{"heading":"Drei Bauformen der Konnektoren","text":"German signals logical relations with three grammatically distinct tools. Conjunctions (weil, obwohl, damit) send the verb to the end of a subordinate clause. Conjunctional adverbs (deshalb, dennoch, folglich) occupy the first position of a main clause and push the verb to second: ''Die Daten sind eindeutig; folglich muss die These revidiert werden.'' Prepositions (wegen, trotz, aufgrund) attach to a noun phrase. Choosing the right form is a frequent exam discriminator."},{"heading":"Konzession und Einschränkung","text":"To argue at C1 you must concede without capitulating. Subordinating: ''Obwohl die Methode umstritten ist, liefert sie belastbare Ergebnisse.'' Adverbial: ''Die Methode ist umstritten; gleichwohl / dennoch liefert sie belastbare Ergebnisse.'' Prepositional: ''Trotz methodischer Bedenken überzeugen die Ergebnisse.'' Rotating these three keeps a paragraph from repeating aber and doch."},{"heading":"Kausalität, Konsequenz, Finalität","text":"Distinguish the direction of the link. Cause: da, weil, aufgrund. Consequence: sodass, infolgedessen, somit (''Die Nachfrage stieg, sodass die Preise anzogen''). Purpose: damit and um ... zu (''Er wiederholt das Argument, um es zu untermauern''). Note that um ... zu needs a shared subject, while damit works even when the subjects differ: ''Ich erkläre es genauer, damit alle folgen können.''"},{"heading":"Kohäsion über den Absatz hinweg","text":"Cohesion is more than connectors. Use resumptive phrases to link paragraphs: ''Dieser Befund wirft eine weitere Frage auf ...'', ''An dieser Stelle ist einzuwenden, dass ...'', ''Damit ist der Kern des Problems benannt.'' Pronominal adverbs (dadurch, hierbei, demzufolge) point back to the previous idea without repeating the noun. A well-structured Erörterung threads one such reference into the opening sentence of every new paragraph."}]}'::jsonb, null, 14),
  (4, 'Redemittel: Abtönung, Distanz und Präzisierung', 'vocab', '{"items":[{"term":"es liegt nahe, dass","translation":"it stands to reason that","ipa":"ɛs liːkt ˈnaːə das","example":"Es liegt nahe, dass wirtschaftliche Faktoren hier eine Rolle spielen."},{"term":"vermutlich / mutmaßlich","translation":"presumably / allegedly","ipa":"fɛɐ̯ˈmuːtlɪç ˈmuːtˌmaːslɪç","example":"Die Ursachen sind vermutlich vielschichtiger, als die Studie andeutet."},{"term":"dem Anschein nach","translation":"seemingly, to all appearances","ipa":"deːm ˈanʃaɪn naːx","example":"Dem Anschein nach handelt es sich um einen Einzelfall, doch die Zahlen sagen anderes."},{"term":"der Autorin zufolge","translation":"according to the author","ipa":"deːɐ̯ aʊˈtoːʁɪn ˈtsuːfɔlɡə","example":"Der Autorin zufolge lässt sich der Trend nicht verallgemeinern."},{"term":"mit Vorbehalt","translation":"with reservations","ipa":"mɪt ˈfoːɐ̯bəˌhalt","example":"Diese Prognose ist nur mit Vorbehalt zu genießen."},{"term":"in gewissem Maße","translation":"to a certain degree","ipa":"ɪn ɡəˈvɪsm̩ ˈmaːsə","example":"Das Argument trifft in gewissem Maße zu, greift aber insgesamt zu kurz."},{"term":"es sei dahingestellt, ob","translation":"it remains open whether","ipa":"ɛs zaɪ ˈdaːhɪnɡəˌʃtɛlt ɔp","example":"Es sei dahingestellt, ob diese Maßnahme wirklich greift."}]}'::jsonb, 'Hedging (Abtönung) is what separates a measured C1 answer from a blunt B2 one. These formulaic phrases let you assert cautiously, distance yourself from a claim, and quote a source responsibly — all rewarded in Goethe and TestDaF marking schemes.', 11),
  (5, 'Lektüre: ein dichter C1-Text und Verständnis', 'reading', '{"sections":[{"heading":"Der Text","text":"Lesen Sie den folgenden Auszug aus einem Meinungsbeitrag: ''Die Digitalisierung des Alltags wird gemeinhin als Fortschritt gefeiert, dessen Kehrseite jedoch selten mitgedacht wird. Zwar erleichtert die ständige Verfügbarkeit von Informationen die Teilhabe am öffentlichen Diskurs; zugleich aber verkürzt sie die Aufmerksamkeitsspannen und begünstigt eine Kultur des flüchtigen Überfliegens. Wer heute eine anspruchsvolle Argumentation entfalten will, sieht sich mit einem Publikum konfrontiert, das an die Häppchenlogik der sozialen Netzwerke gewöhnt ist. Es wäre indes verfehlt, daraus einen kulturellen Niedergang abzuleiten. Vielmehr verschiebt sich lediglich, wie und wo anspruchsvolle Auseinandersetzung stattfindet.''"},{"heading":"Struktur erkennen","text":"Notice the argumentative architecture. The opening concedes the common view (gemeinhin als Fortschritt gefeiert) before flagging its blind spot (dessen Kehrseite selten mitgedacht wird). The ''zwar ... zugleich aber'' pairing stages a controlled tension. The pivot ''Es wäre indes verfehlt, daraus ... abzuleiten'' rejects an overhasty conclusion, and ''Vielmehr'' introduces the writer''s own, more nuanced claim. Mapping these moves is exactly what a comprehension task rewards."},{"heading":"Wortschatz im Kontext","text":"Infer meaning from context rather than reaching for a dictionary. Kehrseite means the downside (literally the reverse side of a coin). flüchtiges Überfliegen is skimming without depth. Häppchenlogik — the logic of bite-sized snippets (Häppchen = canapé) — is an ironic coinage. indes is a formal synonym of jedoch. verfehlt here means mistaken or wide of the mark, not merely ''missed''."},{"heading":"Prüfungsfrage und Antwort","text":"A typical item: ''Welche Haltung nimmt der Verfasser gegenüber der Digitalisierung ein?'' A weak answer says ''Er ist dagegen.'' A C1 answer captures the nuance: ''Der Verfasser bewertet die Digitalisierung ambivalent: Er erkennt Vorteile für die gesellschaftliche Teilhabe an, warnt jedoch vor verkürzter Aufmerksamkeit, weist aber ausdrücklich die These eines kulturellen Niedergangs zurück.'' Note how the answer paraphrases rather than copies, and mirrors the text''s concessive structure."}]}'::jsonb, null, 15),
  (6, 'Die Erörterung strukturiert schreiben', 'writing', '{"sections":[{"heading":"Aufbau der linearen und der dialektischen Erörterung","text":"The Erörterung comes in two shapes. The linear form develops a single thesis through escalating arguments toward a conclusion. The dialectical form weighs Pro against Contra before reaching a reasoned position: introduction, arguments for, arguments against (or vice versa), and a synthesis. Decide the shape from the prompt: ''Diskutieren Sie'' invites the dialectical model; ''Begründen Sie, warum'' invites the linear one."},{"heading":"Die Einleitung","text":"Open with a hook that situates the topic — a current observation, a striking figure, or a pointed question — then narrow to the exact question you will address, and announce your approach. Avoid restating the prompt verbatim. Example: ''Kaum ein Thema wird derzeit so kontrovers diskutiert wie die Vier-Tage-Woche. Ob sie Produktivität und Lebensqualität tatsächlich vereint, ist umstritten. Im Folgenden werden zunächst die zentralen Argumente beider Seiten abgewogen, um daraus eine begründete Position zu entwickeln.''"},{"heading":"Der Hauptteil: Argument, Beleg, Beispiel","text":"Build each paragraph on the three-step Behauptung–Begründung–Beleg pattern: state the claim, justify it, and back it with a concrete example or figure. Rank arguments by weight and save the strongest for last (Steigerung). Signal each new point with a fresh connector — Zunächst, Darüber hinaus, Entscheidend ist jedoch — and close a Pro block before pivoting cleanly: ''So überzeugend diese Argumente erscheinen, sie sind nicht unwidersprochen geblieben.''"},{"heading":"Der Schluss","text":"The conclusion must decide, not merely summarize. Draw the threads together, state your position unambiguously, and, where appropriate, open a measured outlook. Example: ''Wägt man beide Seiten ab, überwiegen die langfristigen Vorteile, sofern die Umsetzung branchenspezifisch erfolgt. Ob sich das Modell flächendeckend durchsetzt, wird letztlich davon abhängen, ob Unternehmen bereit sind, Produktivität neu zu definieren.'' Never introduce a brand-new argument in the final paragraph."}]}'::jsonb, null, 16),
  (7, 'Zusammenfassen und Paraphrasieren ohne Kopieren', 'writing', '{"sections":[{"heading":"Was eine gute Zusammenfassung ausmacht","text":"A C1 summary is written in the present tense, in your own words, and strictly free of your own opinion. It names the source and text type in the first sentence — ''Der vorliegende Artikel von ... aus dem Jahr ... befasst sich mit ...'' — then renders only the main line of thought, dropping examples, repetitions and rhetorical flourishes. Length is typically a third of the original or less."},{"heading":"Techniken des Paraphrasierens","text":"Recasting rather than copying is the core skill. Swap word class (verbalize a nominal phrase or nominalize a verbal one), replace vocabulary with synonyms of equal register (behaupten → die Ansicht vertreten), change voice (active ↔ passive), and reorder clauses. Original: ''Die Regierung hat das Gesetz überraschend verschärft.'' Paraphrase: ''Zur Überraschung vieler wurde das Gesetz von der Regierung verschärft.'' Same content, new surface."},{"heading":"Redemittel der indirekten Rede","text":"Attribute every claim to the source with reporting verbs and, where the register calls for it, Konjunktiv I: ''Der Autor argumentiert, die Maßnahme sei verfrüht.'' ''Die Verfasserin behauptet, es gebe keine belastbaren Daten.'' Vary the reporting verbs — betonen, einräumen, kritisieren, hervorheben — so the summary does not drown in ''sagt'' and ''meint''. Konjunktiv I keeps your own voice audibly separate from the source''s."},{"heading":"Häufige Fehler","text":"Avoid four traps rewarded with lost points: copying whole phrases from the original (plagiarism of surface), slipping in your own evaluation (gut, leider, zu Recht), reproducing examples instead of the underlying claim, and shifting into the past tense. Reread your draft against the source and ask of every sentence: is this the author''s thought, and is it truly in my words?"}]}'::jsonb, null, 14),
  (8, 'Seminardiskussion: eine Position verteidigen', 'roleplay', '{"scenario":"A graduate-seminar discussion in which you defend the thesis that universities should make one semester abroad compulsory. Open with a crisp statement of your position, develop two structured arguments with concrete evidence, respond to a sharp counter-argument by conceding a limited point without abandoning your thesis, and close by restating your stance in one polished sentence. Use hedging and connectors from the earlier lessons — es liegt nahe, dass ...; gleichwohl; entscheidend ist jedoch.","persona":"A demanding Dozentin who moderates in academic German, interrupts with pointed objections (Kosten, soziale Ungleichheit, organisatorischer Aufwand) and repeatedly presses you to substantiate claims with evidence rather than assertion","goal":"Sustain and defend an abstract position in formal spoken German for several turns, rebut at least one objection, concede a minor point gracefully, and deliver a clear closing statement — all in an appropriately academic register"}'::jsonb, null, 14),
  (9, 'Prüfungsstrategie: Goethe- und TestDaF-Technik', 'reading', '{"sections":[{"heading":"Zeitmanagement in der Prüfung","text":"In both the Goethe-Zertifikat C1 and the TestDaF, time pressure fails more candidates than gaps in German. Budget explicitly: in the reading module, allot fixed minutes per text and move on when the clock runs out, marking unanswered items to revisit. In writing, spend a quarter of your time on an outline before drafting. A planned essay of medium length outscores a sprawling, unfinished one almost every time."},{"heading":"Leseverstehen: Fragen zuerst","text":"Read the questions before the text, not after. They tell you what to hunt for, so you can scan (überfliegen) for the relevant passage rather than reading every word closely. Beware distractors that repeat a word from the text but reverse its meaning, and answers that are true in general but not stated in this text. The rule of thumb: the correct option paraphrases the passage; it rarely echoes it word for word."},{"heading":"Schreiben und Sprechen: die Bewertungskriterien kennen","text":"Examiners score on separate axes — task fulfilment (Inhalt), coherence and cohesion (Kohärenz), vocabulary range (Wortschatz) and grammatical accuracy (Korrektheit). You cannot rescue a thin argument with flawless grammar, nor vice versa. Deliberately showcase C1 range: one subjunctive, one passive, one extended attribute, two or three varied connectors per paragraph. In the oral exam, structure aloud — ''Ich möchte auf drei Punkte eingehen. Erstens ...'' — because signposting is itself marked as coherence."},{"heading":"Fehlerkontrolle und Nerven","text":"Reserve the final minutes for targeted proof-reading. Hunt your own recurring weaknesses in order: verb position at the clause end, adjective endings, capitalization of nominalized verbs (das Lesen), and case after two-way prepositions. If a word escapes you mid-sentence, paraphrase rather than freeze — ''ein Gerät, mit dem man ...'' buys you the point that a blank does not. Composure is a skill you can rehearse under a timer at home."}]}'::jsonb, null, 13),
  (10, 'C1-Checkpoint: Sprache, Stil und Strategie', 'quiz', '{"questions":[{"prompt":"Nominalisieren Sie: ''Weil die Kosten stiegen, wurde das Projekt gestoppt.'' Welche Fassung ist korrekt und idiomatisch?","options":["Wegen die steigenden Kosten wurde das Projekt gestoppt.","Aufgrund steigender Kosten wurde das Projekt gestoppt.","Weil steigende Kosten wurde das Projekt gestoppt.","Trotz steigender Kosten wurde das Projekt gestoppt."],"answer":1,"explanation":"aufgrund takes the genitive (steigender Kosten) and expresses cause; wegen would also need the genitive (not ''die''), and trotz reverses the meaning to concession."},{"prompt":"Welcher Konnektor leitet grammatisch einen Hauptsatz ein und stellt das Verb an die zweite Position? ''Die Daten sind eindeutig; ___ muss die These revidiert werden.''","options":["weil","obwohl","folglich","damit"],"answer":2,"explanation":"folglich is a conjunctional adverb: it stands in first position of a main clause and pushes the finite verb (muss) to second. weil, obwohl and damit are subordinating conjunctions that send the verb to the end."},{"prompt":"Welches Funktionsverbgefüge entspricht ''bezweifeln''?","options":["eine Entscheidung treffen","in Frage stellen","zur Sprache bringen","Kritik üben"],"answer":1,"explanation":"etwas in Frage stellen means to cast doubt on / to question something, i.e. bezweifeln. ''eine Entscheidung treffen'' = entscheiden, ''zur Sprache bringen'' = ansprechen, ''Kritik üben'' = kritisieren."},{"prompt":"Was kennzeichnet eine gute C1-Zusammenfassung?","options":["Sie zitiert die stärksten Beispiele wörtlich.","Sie steht im Präteritum und enthält Ihre Bewertung.","Sie gibt im Präsens und in eigenen Worten nur den Hauptgedanken wieder.","Sie ist etwa so lang wie der Originaltext."],"answer":2,"explanation":"A summary is written in the present tense, in your own words, free of personal opinion, and reduced to the main line of thought — examples, quotations and evaluation are left out, and it is markedly shorter than the source."},{"prompt":"Wählen Sie die korrekte indirekte Rede im Konjunktiv I: ''Der Autor sagt: „Es gibt keine belastbaren Daten.“''","options":["Der Autor sagt, es gibt keine belastbaren Daten.","Der Autor sagt, es gäbe keine belastbaren Daten.","Der Autor sagt, es gebe keine belastbaren Daten.","Der Autor sagt, es geben keine belastbaren Daten."],"answer":2,"explanation":"Konjunktiv I of geben in the third person singular is gebe; it marks the statement as reported and keeps the writer''s voice distinct. gäbe is Konjunktiv II, used mainly when Konjunktiv I coincides with the indicative."},{"prompt":"In der Erörterung gilt für den Schluss vor allem:","options":["Ein neues, starkes Argument einführen.","Die Einleitung wörtlich wiederholen.","Eine klare, begründete Position beziehen und die Fäden zusammenführen.","Alle Beispiele des Hauptteils noch einmal aufzählen."],"answer":2,"explanation":"The conclusion draws the arguments together and states a clear, reasoned position; introducing a new argument, repeating the introduction, or merely relisting examples all weaken it."},{"prompt":"Welche Strategie ist im Leseverstehen einer C1-Prüfung am wirksamsten?","options":["Jeden Text zuerst vollständig und langsam lesen.","Zuerst die Fragen lesen und dann gezielt nach den Antworten scannen.","Antworten wählen, die ein Wort aus dem Text wiederholen.","Bei Zeitmangel raten und keine Frage markieren."],"answer":1,"explanation":"Reading the questions first lets you scan for the relevant passages instead of close-reading everything; options that merely echo a word from the text are often distractors, while the correct answer usually paraphrases the passage."}]}'::jsonb, null, 12)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'aaaa0006-0000-4000-8000-000000000004' and l.position = v.pos
);
